// The printed listing imports Set but not HashSet. This small stand-in supplies
// the name so the example compiles and runs exactly as printed; it behaves
// identically to java.util.HashSet.
public class HashSet<E> extends java.util.HashSet<E> {
    public HashSet() {
        super();
    }

    public HashSet(java.util.Collection<? extends E> source) {
        super(source);
    }
}

public class Main {
    public static void main(String[] args) {
        PlaylistApp.main(args);
    }
}
